/// <summary>
/// Maximum a posteriori estimation: finds the mode of a log-posterior density via
/// L-BFGS (datamunge::optim::LBFGS), analogous to Stan's <c>optimizing()</c>.
/// </summary>
public partial class MAP : NativeObject
{
    internal MAP(NativeRaw raw) : base(raw) { }

    /// <summary>
    /// C++ <c>datamunge::bayes::MAP::MAP</c>.
    /// </summary>
    /// <remarks>
    /// <para>Uses the C++ default for <c>options = default</c>.</para>
    /// </remarks>
    public MAP() : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(MAP), false, 450);
    }

    /// <summary>
    /// C++ <c>datamunge::bayes::MAP::MAP</c>.
    /// </summary>
    /// <param name="options"></param>
    public MAP(MAPOptions options) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(MAP), false, 450, options);
    }

    /// <summary>
    /// Maximizes <c>log_posterior</c> starting from <c>coordinates</c>, updating it in place
    /// to the mode found, and returns the log-posterior density there.
    /// </summary>
    /// <param name="logPosterior"></param>
    /// <param name="coordinates"></param>
    public double Optimize(DifferentiableFunction logPosterior, ref List<double> coordinates)
    {
        var _slot1 = new Rosetta.Slot(coordinates);
        var _result = Rosetta.To<double>(Rosetta.Call(448, this, logPosterior, _slot1));
        coordinates = Rosetta.To<List<double>>(_slot1.Value);
        return _result;
    }

