    /// <summary>
    /// C++ <c>datamunge::filter::AlphaBetaFilter::AlphaBetaFilter</c>.
    /// </summary>
    /// <param name="alpha"></param>
    /// <param name="beta"></param>
    /// <param name="dt"></param>
    /// <param name="x0"></param>
    /// <param name="v0"></param>
    public AlphaBetaFilter(double alpha, double beta, double dt, double x0, double v0) : base(default(NativeRaw))
    {
