    /// auto plt = dm::Plot::qqnorm(sample).qqline(sample);
    /// const auto&amp; line = plt.reference_lines()[0];
    /// std::print("{:.4f} {:.4f}\n", line.value, line.slope);  // 3.0000 1.4826
    /// </code>
