    /// const auto x = dm::c(1.0, 2.0, 3.0);
    /// const auto y = dm::c(2.0, 3.5, 3.0);
    /// auto plt = dm::Plot(x, y).segments(x, y - 0.5, x, y + 0.5);  // +/- 0.5 error bars
    /// std::print("{}\n", plt.series()[1].x.size());  // 6 (start, end, start, end, ...)
