    public RPlot Segments(IEnumerable<double> x0, IEnumerable<double> y0, IEnumerable<double> x1, IEnumerable<double> y1, RGB color) => Rosetta.To<RPlot>(Rosetta.Call(1069, this, x0, y0, x1, y1, color));

    /// <summary>
