    {
        Rosetta.Construct(this, typeof(ODESolver), false, 1198, options);
    }

    /// <summary>
    /// C++ <c>datamunge::ode::ODESolver::solve</c>.
    /// </summary>
    /// <param name="rhs"></param>
    /// <param name="y0"></param>
    /// <param name="tStart"></param>
    /// <param name="tEnd"></param>
