/// <summary>
/// Ant Colony Optimization for continuous domains (ACOR), Socha &amp; Dorigo (2008). A
/// solution archive of size k is maintained; each iteration, new ants are sampled from a
/// Gaussian kernel mixture built from the archive (ranked by quality, so better solutions
/// attract denser sampling), then the archive is truncated back to its k best members
/// merged with the new ants. Derivative-free, box-constrained.
/// </summary>
public partial class ACOR : NativeObject
{
    internal ACOR(NativeRaw raw) : base(raw) { }

    /// <summary>
    /// C++ <c>datamunge::optim::ACOR::ACOR</c>.
    /// </summary>
    /// <remarks>
    /// <para>Uses the C++ default for <c>options = default</c>.</para>
    /// </remarks>
    public ACOR() : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(ACOR), false, 1216);
    }

    /// <summary>
    /// C++ <c>datamunge::optim::ACOR::ACOR</c>.
    /// </summary>
    /// <param name="options"></param>
    public ACOR(ACOROptions options) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(ACOR), false, 1216, options);
    }

    /// <summary>
    /// Minimizes <c>function</c> within [<c>lower_bound</c>, <c>upper_bound</c>], updating
    /// <c>coordinates</c> in place to the best point found, and returns its value. The
    /// initial <c>coordinates</c> (clamped into bounds) seed one member of the archive.
    /// </summary>
    /// <param name="function"></param>
    /// <param name="coordinates"></param>
    /// <param name="lowerBound"></param>
    /// <param name="upperBound"></param>
    public double Optimize(ArbitraryFunction function, ref List<double> coordinates, IEnumerable<double> lowerBound, IEnumerable<double> upperBound)
    {
        var _slot1 = new Rosetta.Slot(coordinates);
        var _result = Rosetta.To<double>(Rosetta.Call(1214, this, function, _slot1, lowerBound, upperBound));
        coordinates = Rosetta.To<List<double>>(_slot1.Value);
        return _result;
    }

    /// <summary>
    /// The options this ACOR was configured with.
    /// </summary>
    /// <returns>The stored options.</returns>
    public ACOROptions Options() => Rosetta.To<ACOROptions>(Rosetta.Call(1215, this));
}

