    /// <param name="options">Model orders and optimizer settings.</param>
    /// <exception cref="NativeException">C++ <c>std::invalid_argument</c>: If a seasonal order is set while seasonal_period is zero, or if the series is too short for the requested differencing or AR order.</exception>
    public ARIMA(IEnumerable<double> y, ARIMAOptions options) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(ARIMA), false, 1962, y, options);
