    /// <exception cref="NativeException">C++ <c>std::overflow_error</c>: If difference weights or the penalty overflow.</exception>
    public PSplineRegression(IEnumerable<double> x, IEnumerable<double> y, ulong nBasis, double lambda) : base(default(NativeRaw))
    {
