    /// <para>Uses the C++ default for <c>batchSize = 1000</c>, <c>delimiter = ','</c>.</para>
    /// </remarks>
    /// <param name="path">The CSV file.</param>
    /// <exception cref="NativeException">C++ <c>std::invalid_argument</c>: if batch_size is not positive.</exception>
    /// <exception cref="NativeException">C++ <c>std::runtime_error</c>: if the file cannot be opened or is malformed.</exception>
    public CsvReader(string path) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(CsvReader), false, 2106, path);
    }

    /// <summary>
    /// Opens <c>path</c> and infers its column types.
    /// </summary>
    /// <remarks>
    /// <para>Uses the C++ default for <c>delimiter = ','</c>.</para>
    /// </remarks>
    /// <param name="path">The CSV file.</param>
    /// <param name="batchSize">Rows per chunk; must be positive.</param>
    /// <exception cref="NativeException">C++ <c>std::invalid_argument</c>: if batch_size is not positive.</exception>
    /// <exception cref="NativeException">C++ <c>std::runtime_error</c>: if the file cannot be opened or is malformed.</exception>
    public CsvReader(string path, int batchSize) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(CsvReader), false, 2106, path, batchSize);
    }

    /// <summary>
    /// Opens <c>path</c> and infers its column types.
    /// </summary>
    /// <param name="path">The CSV file.</param>
    /// <param name="batchSize">Rows per chunk; must be positive.</param>
    /// <param name="delimiter">The field separator.</param>
    /// <exception cref="NativeException">C++ <c>std::invalid_argument</c>: if batch_size is not positive.</exception>
    /// <exception cref="NativeException">C++ <c>std::runtime_error</c>: if the file cannot be opened or is malformed.</exception>
    public CsvReader(string path, int batchSize, char delimiter) : base(default(NativeRaw))
    {
        Rosetta.Construct(this, typeof(CsvReader), false, 2106, path, batchSize, delimiter);
    }

    /// <summary>
    /// true while rows remain.
    /// </summary>
