    /// <param name="titleHint">Window title; empty uses the figure title, or "datamunge splom".</param>
    /// <exception cref="NativeException">C++ <c>std::runtime_error</c>: If X11 is unavailable or the display cannot be opened.</exception>
    public void Show(string titleHint) => Rosetta.Call(2176, this, titleHint);
}

