    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
    public static Polynomial PolyGcd(Polynomial a, Polynomial b) => Rosetta.To<Polynomial>(Rosetta.Call(11, a, b));

    /// <summary>
    /// Extended Euclidean algorithm: computes gcd(a, b) along with Bezout coefficients s, t
    /// satisfying <c>s*a + t*b == gcd</c>. <c>gcd</c> is returned monic (s and t are scaled to match).
    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
