    /// <param name="p1"></param>
    /// <param name="q1"></param>
    /// <param name="p2"></param>
    /// <param name="q2"></param>
    public static bool SegmentsIntersect(Point2D p1, Point2D q1, Point2D p2, Point2D q2) => Rosetta.To<bool>(Rosetta.Call(152, p1, q1, p2, q2));

